// Check the email and set the search window: tomorrow onwards, SEARCH_DAYS long.
const SEARCH_DAYS = 7;
const MAX_FIELD = 120;
const clean = (v) => String(v ?? '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, MAX_FIELD);

const lead = $input.first().json;
const email = clean(lead.contact_email).toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  throw new Error('contact_email is missing or is not an email address.');
}

const start = DateTime.now().plus({ days: 1 }).startOf('day');
const end = start.plus({ days: SEARCH_DAYS });

return [{
  json: {
    company: clean(lead.company),
    contact_name: clean(lead.contact_name) || 'there',
    contact_email: email,
    title: clean(lead.title),
    deal_id: clean(lead.deal_id),
    window_start: start.toISO(),
    window_end: end.toISO(),
  },
}];

// First free weekday slot inside working hours. Times are in the instance's
// timezone (GENERIC_TIMEZONE in docker-compose.yml).
const SLOT_MINUTES = 30;
const DAY_START_HOUR = 10;
const DAY_END_HOUR = 16;

const lead = $('Validate Lead').first().json;

// Booked slots can come back as one item per slot or as an array on one item.
const busy = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const list = Array.isArray(j.busy) ? j.busy : [j];
  for (const b of list) {
    if (b && b.start && b.end) busy.push([DateTime.fromISO(b.start), DateTime.fromISO(b.end)]);
  }
}

const windowEnd = DateTime.fromISO(lead.window_end);
let slot = null;
for (let day = DateTime.fromISO(lead.window_start); day < windowEnd && !slot; day = day.plus({ days: 1 })) {
  if (day.weekday > 5) continue;
  const dayEnd = day.set({ hour: DAY_END_HOUR, minute: 0, second: 0, millisecond: 0 });
  let t = day.set({ hour: DAY_START_HOUR, minute: 0, second: 0, millisecond: 0 });
  while (t.plus({ minutes: SLOT_MINUTES }) <= dayEnd) {
    const tEnd = t.plus({ minutes: SLOT_MINUTES });
    const clash = busy.some(([bs, be]) => t < be && tEnd > bs);
    if (!clash) {
      slot = { start: t, end: tEnd };
      break;
    }
    t = tEnd;
  }
}

return [{
  json: {
    ...lead,
    slot_found: slot !== null,
    slot_start: slot ? slot.start.toISO() : null,
    slot_end: slot ? slot.end.toISO() : null,
  },
}];

const lead = $('Pick Slot').item.json;
const event = $('Hold Demo Slot').item.json;
return {
  json: {
    status: 'slot_held_invite_drafted',
    company: lead.company,
    contact_email: lead.contact_email,
    slot_start: lead.slot_start,
    slot_end: lead.slot_end,
    event_id: event.id,
    event_link: event.htmlLink,
    draft_id: $json.id,
    deal_id: lead.deal_id,
  },
};
